package com.starlight.greetings.web; import com.starlight.greetings.application.SurveyMetricsService; import jakarta.servlet.http.HttpServletRequest; import java.util.Map; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class SurveyMetricsController {private final SurveyMetricsService service;public SurveyMetricsController(SurveyMetricsService service){this.service=service;}@GetMapping("/survey") public ApiEnvelope<Map<String,Object>> survey(){return ApiEnvelope.of(service.survey());}@PostMapping("/events") public ResponseEntity<ApiEnvelope<Map<String,Object>>> event(@RequestBody Map<String,Object> input,HttpServletRequest req){return ResponseEntity.status(201).body(ApiEnvelope.of(service.event(input,req.getRemoteAddr())));}@PostMapping("/events/survey-open") public ResponseEntity<ApiEnvelope<Map<String,Object>>> open(@RequestBody Map<String,Object> input,HttpServletRequest req){return ResponseEntity.status(201).body(ApiEnvelope.of(service.surveyOpen(input,req.getRemoteAddr())));}}
